function connectionsPage(){return heading('Platform','Connections','Manage linked training sources and inspect import status.')+`<div class="app-banner"><b>Demo connections</b>No account is connected here. The sample import history lets you explore the workflow without authorizing a device or service.</div><div class="two-col">${['Strava','Garmin','COROS','Oura','Ultrahuman'].map((p,i)=>panel(p,`<span class="badge ${i?'warn':'blue'}">${i?'Coming later / unavailable':'Sample connection'}</span><p class="chart-note">${i?'Explore the planned connection information; no OAuth or data transfer occurs.':'Example status: 12 imported activities, last sample sync Oct 7.'}</p><button class="button small outline" style="margin-top:16px" data-action="x-connection" data-provider="${p}">View ${p} details</button>`)).join('')}${panel('Import health',`<div class="metrics"><div class="metric"><b>12</b><small>Sample imported</small></div><div class="metric"><b>1</b><small>Needs matching</small></div><div class="metric"><b>0</b><small>Duplicates</small></div></div><button class="button small outline" style="margin-top:20px" data-action="x-import" data-id="${selected}">Inspect sample import</button>`)}</div>`;}
