function notificationPage(){return heading('Account','Notifications','Choose the updates you want and review recent coaching activity.')+`<div class="two-col">${panel('Notification preferences',`<form id="x-notification-form">${[['messages','Direct messages','New athlete and coach conversations'],['comments','Workout comments','Feedback attached to a session'],['checkins','Athlete check-ins','Updates that might need a plan adjustment'],['digest','Weekly digest','A summary of coaching activity']].map(([id,t,sub])=>`<label class="toggle-row"><input type="checkbox" name="${id}" ${state.notificationPrefs[id]?'checked':''}><span><b>${t}</b><small>${sub}</small></span></label>`).join('')}<button class="button" type="submit">Save preferences</button>${sample}</form>`)}${panel('Recent notifications',[['n1','Maya sent a check-in','Schedule change requested'],['n2','Eli commented on a workout','Tempo feedback to review'],['n3','Jordan logged recovery','Higher soreness reported']].map(([id,t,p])=>`<div class="history-row"><div><h3>${t}</h3><p>${p}</p></div><button class="button small outline" data-action="x-read-notification" data-id="${id}" ${state.readNotifications.includes(id)?'disabled':''}>${state.readNotifications.includes(id)?'Read ✓':'Mark read'}</button></div>`).join(''))}</div>`;}
