function supportPage(){return heading('Help / Billing','Support','A guide to exploring this fictional coaching workspace.')+`<div class="two-col">${panel('Demo help',`<p class="chart-note">Use Navigation to reach every coaching, training, research, and account page. Saved changes affect only this browser.</p><a class="button small outline" href="#guide">Open guide</a><a class="button small outline" href="#feedback">Share your feedback</a>`)}${panel('What is simulated?',`<p class="chart-note">All athlete records, messages, check-ins, imports, and account details are fictional. Connections, invitation delivery, billing, and live research queries are not executed. Local edits, group assignments, calculations, resource saving, and feedback export work.</p>`)}</div>`;}
Object.assign(demoViews,{tools:toolsPage,groups:groupsPage,dashboard:dashboardPage,races:racesPage,'race-plan':blueprintPage,'check-in':checkinPage,'log-intervention':loggerPage,history:historyPage,progress:progressPage,explorer:explorerPage,research:researchPage,connections:connectionsPage,settings:settingsPage,account:accountPage,notifications:notificationPage,pricing:pricingPage,support:supportPage});
// Render hooks keep calculator output and mobile active states consistent after navigation.
const coreRoute=route,coreRefresh=refresh;
function afterRender(){updateTools();const hash=(location.hash.slice(1)||'overview').split('/')[0];document.querySelectorAll('.mobile-bottom a').forEach(a=>{if(a.hash===`#${hash}`)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});}
route=()=>{coreRoute();afterRender();};refresh=()=>{coreRefresh();afterRender();};
function protocolDialog(id){if(id)selected=person(id).id;showDialog('Assign protocol',`<form id="x-protocol-form">${selectField('Athlete','athlete',athletes.map(a=>[a.id,a.name]),selected)}${selectField('Protocol type','title',['Sleep consistency','Long-run fueling practice','Gut Training','Heat Acclimation','Sauna - Recovery'],'Sleep consistency')}<div class="form-grid">${field('Start date','start','2026-10-09','date','required')}${field('End date','end','2026-10-23','date','required')}${field('Compliance target (%)','target',85,'number','min="0" max="100" required')}</div>${textarea('Coach instructions','detail','','required')}<div class="actions"><button class="button outline" type="button" data-action="close">Cancel</button><button class="button" type="submit">Assign in demo</button></div>${sample}</form>`);}
function raceDialog(id){const r=state.races.find(r=>r.id===id)||{id:'',athlete:selected,name:'',date:'2026-11-01',distance:'Marathon',priority:'A'};showDialog(r.id?'Edit race':'Add a race',`<form id="x-race-form" data-id="${r.id}">${selectField('Athlete','athlete',athletes.map(a=>[a.id,a.name]),r.athlete)}${field('Race name','name',r.name,'text','required maxlength="150"')}<div class="form-grid">${field('Race date','date',r.date,'date','required')}${selectField('Distance','distance',['5K','10K','Half Marathon','Marathon','50K','100K','Other'],r.distance)}${selectField('Priority','priority',['A','B','C'],r.priority)}</div><button class="button" type="submit">Save race</button>${sample}</form>`);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const act=b.dataset.action,id=b.dataset.id;switch(act){
  case 'site-menu':showDialog('Navigation',`<div class="menu-list">${sections.map(([label,items])=>`<section><p>${label}</p>${items.map(([p,t])=>`<a href="#${p}">${t}</a>`).join('')}</section>`).join('')}</div>`);break;
  case 'x-command-tab':commandTab=id;refresh();break;
  case 'x-depth':depth=id;refresh();break;
  case 'x-advanced-tab':advancedTab=id;refresh();break;
  case 'x-insight-tab':insightTab=id;refresh();break;
  case 'x-protocol':protocolDialog(id);break;
  case 'x-protocol-status':{const p=state.protocols[Number(b.dataset.index)];p.status=p.status==='Completed'?'In progress':'Completed';record('protocol_status');refresh();toast('Protocol status updated.');break;}
  case 'x-invite':showDialog('Invite an athlete',`<p>Create a fictional invitation preview. No email is sent and no account is created.</p><form id="x-invite-form">${field('Athlete name','name','','text','required maxlength="150"')}${field('Athlete email (demo only)','email','athlete@example.test','email','required')}<button class="button" type="submit">Create sample invitation</button></form>`);break;
  case 'x-document':showDialog('Share a document',`<form id="x-document-form">${selectField('Athlete','athlete',athletes.map(a=>[a.id,a.name]),id||selected)}${field('Title','title','','text','required maxlength="150"')}${selectField('Category','category',['General','Training','Nutrition','Recovery','Race preparation'],'General')}${textarea('Document text','body','','required')}<button class="button" type="submit">Share in demo</button>${sample}</form>`);break;
  case 'x-open-document':{const d=state.documents.find(d=>d.id===id);showDialog(esc(d.title),`<span class="badge">${esc(d.category)} · ${person(d.athlete).name}</span><p class="note-box">${esc(d.body)}</p>${sample}`);record('open_document');break;}
  case 'x-import':showDialog('TrainingPeaks import · sample report',`<p>${person(id).name} · Four fictional import records.</p><div class="history-row"><div><h3>Easy run · matched</h3><p>Duration 35 min · planned session found</p></div><span class="badge">Matched</span></div><div class="history-row"><div><h3>Tempo run · matched</h3><p>Duration 55 min · athlete comment retained</p></div><span class="badge">Matched</span></div><div class="history-row"><div><h3>Long run · matched</h3><p>Duration 100 min · no duplicate</p></div><span class="badge">Matched</span></div><div class="history-row"><div><h3>Additional easy run</h3><p>No planned session found in this sample.</p></div><span class="badge warn">Needs review</span></div><div class="actions"><a class="button small" href="#calendar">Review calendar</a></div>${sample}`);record('review_import');break;
  case 'x-group-members':{const g=state.groups.find(g=>g.id===id);showDialog('Group members',`<form id="x-member-form" data-id="${id}">${athletes.map(a=>`<label class="member-choice"><input type="checkbox" name="member" value="${a.id}" ${g.members.includes(a.id)?'checked':''}>${a.name}</label>`).join('')}<button class="button" type="submit">Save members</button></form>`);break;}
  case 'x-race':raceDialog(id);break;
  case 'x-blueprint':blueprintRace=id;location.hash='race-plan';break;
  case 'x-intervention-type':$('#x-intervention-form [name=type]').value=b.dataset.type;break;
  case 'x-research-tab':savedOnly=id==='saved';refresh();break;
  case 'x-clear-study':researchQuery='';savedOnly=false;refresh();break;
  case 'x-bookmark':if(state.bookmarks.includes(id))state.bookmarks=state.bookmarks.filter(v=>v!==id);else state.bookmarks.push(id);record('save_study');refresh();break;
  case 'x-study':{const s=studyFixtures.find(s=>s.id===id);showDialog(s.title,`<span class="badge warn">Illustrative sample entry</span><p class="note-box">${s.body}</p><p class="chart-note">This record demonstrates the product’s research reading workflow. It is not a quotation or a real published study.</p>`);record('read_study');break;}
  case 'x-connection':showDialog(`${esc(b.dataset.provider)} connection`,`<p>No ${esc(b.dataset.provider)} account is connected to this research demo. External authentication and data transfer are not available here.</p><div class="app-banner"><b>Connection workflow</b>In the product, authorized providers can supply activity data. This demo shows fictional import status and matching outcomes.</div><button class="button small outline" data-action="x-import" data-id="${selected}">View sample import report</button>`);record('connection_details');break;
  case 'x-read-notification':state.readNotifications.push(id);record('read_notification');refresh();break;
  case 'x-reset':$('#reset').click();break;
  case 'confirm-reset':addDefaults();refresh();break;
}});
document.addEventListener('submit',e=>{const form=e.target;if(!form.id.startsWith('x-')){if(form.classList.contains('tool-form'))e.preventDefault();return;}e.preventDefault();const d=Object.fromEntries(new FormData(form));const done=label=>{record(label);closeDialog();refresh();toast('Saved in the demo. Changes stay in this browser.');};switch(form.id){
  case 'x-profile-form':Object.assign(state.profile,d);done('save_profile');break;
  case 'x-settings-form':Object.assign(state.profile,d);done('save_settings');break;
  case 'x-protocol-form':if(d.end<d.start){toast('Choose an end date after the start date.');return;}state.protocols.push({...d,status:'In progress'});done('assign_protocol');break;
  case 'x-invite-form':state.invitations.push({...d,id:'inv-'+Date.now()});record('create_invitation');showDialog('Sample invitation created',`<p>${esc(d.name)} · ${esc(d.email)}</p><div class="app-banner"><b>DEMO-ALEX</b>Invitation preview only. No email was sent.</div><a class="button outline" href="#dashboard">Preview athlete entry</a>`);break;
  case 'x-document-form':state.documents.push({...d,id:'doc-'+Date.now()});done('share_document');break;
  case 'x-group-form':if(!d.name.trim())return;state.groups.push({id:'group-'+Date.now(),name:d.name.trim(),description:d.description,members:new FormData(form).getAll('member')});done('create_group');break;
  case 'x-member-form':state.groups.find(g=>g.id===form.dataset.id).members=new FormData(form).getAll('member');done('edit_group_members');break;
  case 'x-group-workout-form':{const g=state.groups.find(g=>g.id===d.group),t=library.find(t=>t.id===d.template),offset=Math.round((Date.parse(d.date+'T00:00:00Z')-Date.UTC(2026,9,5))/86400000);if(!g?.members.length){toast('Choose a group with at least one athlete.');return;}g.members.forEach((athlete,i)=>state.workouts.push({id:`group-workout-${Date.now()}-${i}`,athlete,week:Math.floor(offset/7),day:((offset%7)+7)%7,title:t.title,type:t.type,duration:t.duration,description:t.description,done:false}));done('group_workout');break;}
  case 'x-group-protocol-form':{const g=state.groups.find(g=>g.id===d.group);if(!g?.members.length){toast('Choose a group with at least one athlete.');return;}if(d.end<d.start){toast('Choose an end date after the start date.');return;}g.members.forEach(athlete=>state.protocols.push({athlete,title:d.title,start:d.start,end:d.end,target:85,status:'In progress',detail:'Sample group assignment. Discuss the protocol details with your coach.'}));done('group_protocol');break;}
  case 'x-race-form':{const existing=state.races.find(r=>r.id===form.dataset.id);if(existing)Object.assign(existing,d);else state.races.push({...d,id:'race-'+Date.now(),strategy:''});done('save_race');break;}
  case 'x-blueprint-form':Object.assign(state.races.find(r=>r.id===form.dataset.id),{strategy:d.strategy,time:d.time,equipment:d.equipment});done('save_blueprint');break;
  case 'x-intervention-form':state.interventions.push({...d,id:'intervention-'+Date.now()});record('log_intervention');location.hash='history';toast('Intervention saved to sample history.');break;
  case 'x-checkin-form':state.checkins[d.athlete]=d;done('daily_checkin');break;
  case 'x-notification-form':for(const k of Object.keys(state.notificationPrefs))state.notificationPrefs[k]=form.elements[k].checked;done('notification_preferences');break;
  case 'x-explorer-form':$('#explorer-result').innerHTML=`<h3>${esc(d.intervention)} × ${esc(d.outcome)}</h3><p class="chart-note">Six fictional observations for this comparison. No causal conclusion can be drawn from sample data.</p>${chart(person('eli'))}`;record('explore_data');break;
}});
document.addEventListener('input',e=>{if(e.target.closest('.tool-form'))updateTools();if(e.target.id==='study-search'){researchQuery=e.target.value;$('#study-list').innerHTML=studyRows(studyFixtures.filter(s=>(!savedOnly||state.bookmarks.includes(s.id))&&`${s.title} ${s.topic} ${s.sport}`.toLowerCase().includes(researchQuery.toLowerCase())));}});
document.addEventListener('change',e=>{if(e.target.closest('.tool-form'))updateTools();if(e.target.form?.id==='x-blueprint-form'&&e.target.name==='race'){blueprintRace=e.target.value;refresh();}if(e.target.form?.id==='x-checkin-form'&&e.target.name==='athlete'){selected=e.target.value;refresh();}});
document.body.insertAdjacentHTML('beforeend','<a class="floating-message" href="#messages">Coach Messages ↗</a>');
